{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fremstiller det meste af indholdet som 'nyttigt' og 'bør', ikke som krævede oplysninger. Det udelader, at oplysningerne skal fremsendes, når de er tilgængelige i journalen. Det nævner heller ikke minimumskravet om journaler. Det gør dermed lægefaglige oplysninger, som vejledningen kræver, til valgfrie. Det er en væsentlig juridisk unøjagtighed i forhold til rubrikken. Udsagnet om, at 'lægen behøver ikke konkludere', er desuden ikke støttet af kilderne."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Diagnose, forløb, påvirkning af funktion, behandling og prognose er dækket. Det er også dækket, at erhvervsevnen er central. Der mangler dog det kritiske element om, at oplysningerne skal fremsendes, når de er tilgængelige i journalen eller anden eksisterende dokumentation. Planlagt behandling er kun svagt dækket ('igangværende eller afprøvet behandling'). Kravet om varig funktionsnedsættelse og aktualitet nævnes ikke, og heller ikke art og grad."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive, og går ikke ud over spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lov, bekendtgørelse eller vejledning. Det henviser kun generelt til 'SU's aktuelle vejledning'."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer påstande uden støtte i materialet: at SU vurderer sagen, og at lægen ikke behøver at konkludere om ret til tillægget. Det hævder desuden, at 'en diagnose alene normalt ikke er nok', og at dokumentationen så vidt muligt bør beskrive samlet betydning ved flere problemer. Flere af de nævnte elementer, fx bivirkninger, prognose og mødestabilitet, er ikke i kilderne. Samlet er der væsentligt indhold uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdene 'hvis diagnose er stillet', 'hvis behandling er planlagt' og 'hvis muligt' for erhvervsevnen bevares ikke. Forbeholdet om tilgængelighed i journalen mangler også. Svaret gør erhvervsevnen til hovedpunktet uden 'hvis muligt'."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende, og konklusionerne følger af de oplistede punkter. Der er ingen indre modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'bør', 'nyttigt' og 'ofte mere nyttige' om oplysninger, som vejledningen angiver som 'skal fremsendes', når de er tilgængelige. Det gør obligatoriske elementer til anbefalinger. Samtidig er erhvervsevnen gjort til det primære krav, selvom vejledningen siger 'hvis muligt'."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "partial",
      "reason": "Svaret nævner diagnose ('hvad du fejler'), men ikke forbeholdet 'hvis der er stillet en'. Det siger heller ikke, at diagnose ikke er et ubetinget krav."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret nævner diagnose og forløb samt hvordan tilstanden har udviklet sig, hvilket svarer til sygdomsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Svaret nævner igangværende eller afprøvet behandling, effekt og bivirkninger, hvilket dækker behandlingsforløbet."
    },
    "A45": {
      "label": "partial",
      "reason": "Svaret nævner kun 'igangværende eller afprøvet behandling' og 'forventninger til varighed'. Planlagt behandling er ikke nævnt eksplicit, og forbeholdet 'hvis planlagt' mangler."
    },
    "A47": {
      "label": "partial",
      "reason": "Svaret beskriver påvirkningen af mulighed for lønnet arbejde, men uden forbeholdet 'hvis muligt'. Det fremstiller punktet som det primære krav."
    }
  },
  "overall_notes": "Svaret er praktisk og relevant, men angiver ingen kilder. Det omformulerer krav til anbefalinger og udelader kravet om, at tilgængelige oplysninger skal fremsendes. Forbeholdene 'hvis stillet', 'hvis planlagt' og 'hvis muligt' mangler, og flere påstande har ikke støtte i kilderne."
}

